  ],
  "steps": [
    {
      "name": "Clamp",
      "entry": "Pallet arrives at test position (ZS-2008 / X23 rising edge) with cell in auto mode (SS-0003 / X2), no active ST20 fault (M299 OFF), and station idle (M200 OFF).",
      "exit": "Clamp confirmed closed (ZS-2002A / X20 ON) and clamp open sensor clear (ZS-2002B / X21 OFF)."
    },
    {
      "name": "Fill",
      "entry": "Clamp confirmed closed (M201 exit condition satisfied).",
      "exit": "Pack pressure PT-2001 reaches fill threshold (14.50 kPa / D100 >= D122) or fill timeout timer (T21 / 8.0 s) elapses."
    },
    {
      "name": "Stabilise",
      "entry": "Pack pressure reaches fill threshold (14.50 kPa).",
      "exit": "Stabilisation timer (T22) elapses (3 s per narrative / 5.0 s per parameter sheet)."
    },
    {
      "name": "Test",
      "entry": "Stabilisation timer (T22) done.",
      "exit": "Test window timer (T23 / 10.0 s) elapses."
    },
    {
      "name": "Vent",
      "entry": "Test window timer (T23) elapses, or station aborts due to an active fault (M299) while busy.",
      "exit": "Vent timer elapses, pack pressure PT-2001 drops below 1.00 kPa, and PT-2001 signal is healthy (M292 OFF)."
    },
    {
      "name": "Unclamp",
      "entry": "Vent time elapsed, pack pressure < 1.00 kPa, and PT-2001 signal healthy.",
      "exit": "Clamp confirmed open (ZS-2002B / X21 ON) and clamp closed sensor clear (ZS-2002A / X20 OFF)."
    },
    {
      "name": "Done",
      "entry": "Clamp confirmed open (M206 exit condition satisfied).",
      "exit": "Pallet departs test position (ZS-2008 / X23 OFF)."
    }
  ],
  "interlocks": [
    {
      "cause": "Cell not in auto mode (X2 OFF), ST20 fault active (M299 ON), or station busy (M200 ON)",
      "effect": "Inhibit test cycle start upon pallet arrival."
    },
    {
      "cause": "Pallet sensor (ZS-2008 / X23) transitions while test cycle is running",
      "effect": "Inhibit sequence restart."
    },
    {
      "cause": "Clamp not confirmed closed (ZS-2002A / X20 OFF or ZS-2002B / X21 ON)",
      "effect": "Inhibit opening of fill valve XV-2003 (Y21); close fill valve immediately if clamp signal is lost."
    },
    {
      "cause": "Pack pressure PT-2001 at or above 1.00 kPa or PT-2001 signal fault active (M292 ON)",
      "effect": "Inhibit clamp release and hold station in VENT step with vent valve XV-2004 (Y22) open."
    },
    {
      "cause": "Active fault (M299 ON) or E-stop chain lost (X0 OFF) while station is busy (M200 ON)",
      "effect": "Abort sequence to VENT step (M205) and latch FAIL result (M211)."
    },
    {
      "cause": "Overpressure condition detected (PT-2001 / D100 > 20.00 kPa / D123)",
      "effect": "De-energise fill valve XV-2003, hold vent valve XV-2004 open, latch overpressure alarm (M291), and set FAIL result."
    },
    {
      "cause": "Manual vent pushbutton PB-2010 (X25) pressed while cell is in manual mode (X2 OFF)",
      "effect": "Open vent valve XV-2004 (Y22)."
    },
    {
      "cause": "Station not in DONE step (M207 OFF)",
      "effect": "Inhibit transmission of PASS (RS-2006 / Y23) and FAIL (RS-2007 / Y24) signals to line controller."
    }
  ],
  "alarms": [
    {
      "name": "Fill timeout",
      "condition": "Pack pressure PT-2001 fails to reach 14.50 kPa within 8.0 s (T21 done)",
      "action": "Set alarm M290, abort sequence to VENT, set FAIL result (M211), and energise ST20 fault beacon HL-2011 (Y25)."
    },
    {
      "name": "Over-pressure",
      "condition": "Pack pressure PT-2001 exceeds 20.00 kPa (D100 > D123)",
      "action": "Latch alarm M291, close fill valve, open vent valve, set FAIL result, and energise ST20 fault beacon HL-2011 (Y25)."
    },
    {
      "name": "PT-2001 signal fault",
      "condition": "PT-2001 reading drops below -5.00 kPa (D100 < K-500 indicating wire break)",
      "action": "Set alarm M292, inhibit cycle start, hold unclamp in VENT, and energise ST20 fault beacon HL-2011 (Y25)."
    },
    {
      "name": "Supply air low",
      "condition": "PS-2009 supply air pressure switch lost (X22 OFF) while station is busy (M200 ON)",
      "action": "Latch alarm M293, abort sequence to VENT, set FAIL result, and energise ST20 fault beacon HL-2011 (Y25)."
    },
    {
      "name": "E-stop chain lost",
      "condition": "E-stop chain healthy contact ES-0001 lost (X0 OFF) while station is busy",
      "action": "Abort sequence to VENT, set FAIL result, and energise ST20 fault beacon HL-2011 (Y25)."
    }
  ],
  "conflicts": [
    {
      "item": "stabilise_time",
      "narrative_says": "3 s (Section 4.4 states pack settles for 3 s)",
      "parameter_sheet_says": "5.0 s (device T22; changed from 3.0 s by MOC-2021-044)",
      "program_says": "5.0 s (R13 executes OUT T22 K50, which is 5.0 s on 100 ms timer base)",
      "authoritative": "Parameter sheet"
    },
    {
      "item": "vent_time",
      "narrative_says": "0.5 s (Section 4.7 states vent valve opens for 0.5 s)",
      "parameter_sheet_says": "0.5 s (device T24)",
      "program_says": "5.0 s (R21 executes OUT T200 K50; on FX5 OUT is 100 ms base, yielding 5.0 s instead of 0.5 s, and uses timer device T200 instead of T24)",
      "authoritative": "Parameter sheet"
    },
    {
      "item": "test_pressure",
      "narrative_says": "15.2 kPa (Section 4.3 mentions regulator setpoint of 15.2 kPa)",
      "parameter_sheet_says": "15.00 kPa(g) (note mentions supply regulator set to 15.2 kPa)",
      "program_says": "Not configured in PLC logic (mechanical regulator PR-2012)",
      "authoritative": "Parameter sheet"
    }
  ]
}
